INSERT INTO `biz_graphic` VALUES ('2123993222130520066', '测试', NULL, '[\"/snowy/dev/file/download?id=2123993216082333698&sign=YmU4MDQyNzFhNTExMzIyMmRhZmE2M2NkYzc5N2RiYzc3MTNhNzUwNjU1OWYxYzlmNjQzZThiNGI3OWNlY2Q4OQ==\",\"/snowy/dev/file/download?id=2123993218401783809&sign=NzcwMjUyZGVmZDdmNmU4NDkxODk1MTZjZjE5OTc3Yzc0ZmMyMDZlYTg1NTIyY2ZmNzBjYmFhNTg5YzE1NDRlNw==\",\"/snowy/dev/file/download?id=2123993219551023105&sign=NzRkZWEyMmZmNzcwMmUzNWM0OWVmYWJmNDJhNTY2NzdmYWQ4OTM0ZWEwYzlkNmI5ZWUxYzk5OWU1ZjE2Y2M3OA==\",\"/snowy/dev/file/download?id=2123993220301803522&sign=YjhiOGFlYTEyN2M5ZjcwYjg0NmNmMmZkMTQ3Zjg2YzliMGE0NzY1NTIwMmVmNmYxMzMwY2I0YjVkZmFiZjgzYw==\",\"/snowy/dev/file/download?id=2123993221484597250&sign=NzM1NmZkYWY3NGJlMmYxZmJmZjJjOWJmOTg1ZjJmMWY5ZWZjZWFlNjdjOWEzMTcwYTI3NTE4YzdlZTliY2FjNQ==\"]', NULL, '## ✅ 补充：日本 AI 虚拟人像站（无真人肖像风险，最稳）\n\nあぎ AI 模特图库（虚拟女生），全部 AI 生成虚拟人物，不存在真人肖像权，适合壁纸\n[https://huggingface.co/agimodel](https://huggingface.co/agimodel)\n\n- 都是虚拟日系女生，4K PNG，可直接本地自用\n\n## ❌ 绝对不要碰的（写真、粉丝向、模特投稿站）\n\nPixiv、Fantia、FANBOX、ニコニコ静画、各写真博主个人站\n\n- 这些图片版权、肖像权都在画师 / 模特手里，**哪怕你本地爬，法律风险极高**，擦边内容很容易踩红线\n\n## ✅ 折中批量方案（不是爬虫，合规）\n\n1', 'cat_mwpw2qv6j4ft', NULL, 'PUBLISHED', NULL, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, 'NOT_DELETE', '2026-11-21 12:13:41', '1543837863788879873', '2026-11-21 18:59:00', '1543837863788879873');
